ninesliceComponent.event:
				

	component("width"):SetFloat( 0 );
	component("height"):SetFloat( $height );
	component("topHeight"):SetFloat( 16 );
	component("bottomHeight"):SetFloat( 16 );
	component("leftWidth"):SetFloat( 16 );
	component("rightWidth"):SetFloat( 16);
	component("spriteName"):SetString("gfx/menu/popup_bg")
	component("layer"):SetString("$layer")
	component("showing"):SetInt(0)
	component("hiding"):SetInt(0)

if ( component("showing"):GetInt() == 1 ) or ( component("hiding"):GetInt() == 1 ) then local totalTime = component("totalTime"):GetFloat() local t = component("t"):GetFloat() if t < totalTime then local v1 = component("vFrom"):GetFloat() local v2 = component("vTo"):GetFloat() local easedTime = 0 if component("showing"):GetInt() == 1 then easedTime = Back_EaseOut(t, 0, 1, totalTime) end if component("hiding"):GetInt() == 1 then easedTime = Back_EaseIn(t, 0, 1, totalTime) end local v = lerpf( v1, v2, easedTime ) t = t + dt component("t"):SetFloat(t) component("width"):SetFloat( v );
local pos = component:position() game.setWorldClipping("PIRATE_MAP_HUD_CLIPPED", pos.x-14, pos.y-14, component("width"):GetFloat()+28, component("height"):GetFloat()+28);
else if component("showing"):GetInt() == 1 then component("showing"):SetInt(0) element:DoStoredScript("onDoneShow") end if component("hiding"):GetInt() == 1 then component("hiding"):SetInt(0) element:DoStoredScript("onDoneHide") end element("animating"):SetInt(0) end end
